import React from 'react';
import ProcessCard from './ProcessCard'; // Assuming ProcessCard will be created

// Sample data for now - this will come from an API call later
const sampleProcesses = [
  { id: '1', title: 'Sample Process 1', description: 'This is a short description for sample process 1.', createdAt: '2023-01-15' },
  { id: '2', title: 'Sample Process 2', description: 'Another brief overview for the second sample process here.', createdAt: '2023-02-20' },
  { id: '3', title: 'Sample Process 3', description: 'Details about the third process.', createdAt: '2023-03-10' },
];

const ProcessGrid = ({ processes = sampleProcesses }) => {
  const gridStyle = {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', // Responsive grid columns
    gap: 'var(--spacing-unit, 16px)', // Using CSS variable with fallback
    padding: 'var(--spacing-unit, 16px) 0',
  };

  if (!processes || processes.length === 0) {
    return <p>No processes found. Click "Create New Process" to get started!</p>;
  }

  return (
    <div style={gridStyle}>
      {processes.map(process => (
        <ProcessCard key={process.id} process={process} />
      ))}
    </div>
  );
};

export default ProcessGrid;
